"""Research provider contract and a deterministic fake for tests.

The provider is the ONLY component allowed to talk to the outside world (search,
fetch, LLM). It returns *candidates* — claims plus quotes plus source text —
and never scores. Validation and scoring happen downstream and are deterministic.

Contract for a real provider (not implemented yet):
  * ``source.url`` must be the page the provider actually fetched;
  * ``source_text`` must be the fetched page text, never text generated by a model
    (otherwise a model claim would validate itself);
  * ``quote`` must be copied verbatim from that text.

No real network calls happen in this module: ``FakeResearchProvider`` is used by
all tests, so the suite never spends money.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, Mapping, Protocol

from .evidence import EvidenceCandidate, EvidenceError, Source

RESEARCH_OK = "ok"
RESEARCH_INSUFFICIENT = "insufficient_evidence"
RESEARCH_SOURCE_UNAVAILABLE = "source_unavailable"
RESEARCH_PROVIDER_ERROR = "provider_error"
RESEARCH_STATUSES = (
    RESEARCH_OK,
    RESEARCH_INSUFFICIENT,
    RESEARCH_SOURCE_UNAVAILABLE,
    RESEARCH_PROVIDER_ERROR,
)

APPLICABLE = "applicable"
NOT_APPLICABLE = "not_applicable"
APPLICABILITY = (APPLICABLE, NOT_APPLICABLE)


@dataclass(frozen=True)
class AssessmentProposal:
    """The research model's structured answer for ONE questionnaire parameter.

    The model makes three decisions: is the parameter applicable, is the evidence
    sufficient, and (only then) which of the five allowed scores applies. This
    object is a *proposal*: the deterministic layer validates it and may reject or
    downgrade it (never invent a score on its behalf).
    """

    parameter_id: str
    applicability: str = APPLICABLE
    applicability_reason: str = ""
    sufficient: bool = False
    score: int | None = None
    rationale: str = ""
    limitations: tuple[str, ...] = ()
    contradictions: tuple[str, ...] = ()
    important_unknowns: tuple[str, ...] = ()
    evidence_refs: tuple[int, ...] = ()   # indices into ResearchOutcome.candidates

    def __post_init__(self) -> None:
        if not str(self.parameter_id).strip():
            raise EvidenceError("assessment proposal requires parameter_id")
        if self.score is not None and not isinstance(self.score, int):
            raise EvidenceError(f"proposal score must be an integer or null: {self.score!r}")

    def as_dict(self) -> dict:
        return {
            "parameter_id": self.parameter_id,
            "applicability": self.applicability,
            "applicability_reason": self.applicability_reason,
            "sufficient": self.sufficient,
            "score": self.score,
            "rationale": self.rationale,
            "limitations": list(self.limitations),
            "contradictions": list(self.contradictions),
            "important_unknowns": list(self.important_unknowns),
            "evidence_refs": list(self.evidence_refs),
        }


@dataclass(frozen=True)
class ResearchRequest:
    """One questionnaire parameter of one product composition to research.

    ``parameter_definition`` is the exact question this research must answer, so
    the stored result is reusable by any user with the same questionnaire answer
    and never depends on the personal profile that triggered it.
    """

    product_id: int
    product_name: str
    composition_hash: str
    ingredients: tuple[str, ...]
    parameter_id: str
    parameter_label: str
    method_version: str
    scale_anchors: tuple[tuple[int, str], ...] = ()
    parameter_question: str = ""
    parameter_definition: str = ""

    def as_dict(self) -> dict:
        return {
            "product_id": self.product_id,
            "product_name": self.product_name,
            "composition_hash": self.composition_hash,
            "ingredients": list(self.ingredients),
            "parameter_id": self.parameter_id,
            "parameter_label": self.parameter_label,
            "parameter_question": self.parameter_question,
            "parameter_definition": self.parameter_definition,
            "method_version": self.method_version,
        }


@dataclass(frozen=True)
class ResearchOutcome:
    status: str
    candidates: tuple[EvidenceCandidate, ...] = ()
    proposal: AssessmentProposal | None = None
    error: str = ""
    provider: str = ""
    tokens_in: int = 0
    tokens_out: int = 0
    cost_usd: float = 0.0

    def __post_init__(self) -> None:
        if self.status not in RESEARCH_STATUSES:
            raise EvidenceError(f"unknown research status: {self.status}")
        if self.cost_usd < 0:
            raise EvidenceError("cost_usd must not be negative")
        if self.status == RESEARCH_OK and not self.candidates:
            raise EvidenceError("status=ok requires at least one candidate")
        if self.status == RESEARCH_OK and self.proposal is None:
            raise EvidenceError("status=ok requires an assessment proposal")


class ResearchProvider(Protocol):
    name: str

    def research(self, request: ResearchRequest) -> ResearchOutcome: ...


Response = ResearchOutcome | Callable[[ResearchRequest], ResearchOutcome]


class FakeResearchProvider:
    """Deterministic provider for tests: no network, no cost, full call log."""

    name = "fake"

    def __init__(
        self,
        responses: Mapping[object, Response] | None = None,
        *,
        default: Response | None = None,
    ) -> None:
        self._responses: dict = dict(responses or {})
        self._default = default
        self.calls: list[ResearchRequest] = []
        self.total_cost = 0.0

    def set_response(self, key: object, response: Response) -> None:
        self._responses[key] = response

    def call_count(self, parameter_id: str | None = None) -> int:
        if parameter_id is None:
            return len(self.calls)
        return sum(1 for call in self.calls if call.parameter_id == parameter_id)

    def research(self, request: ResearchRequest) -> ResearchOutcome:
        self.calls.append(request)
        response = self._lookup(request)
        if response is None:
            outcome = ResearchOutcome(status=RESEARCH_INSUFFICIENT, provider=self.name)
        elif callable(response):
            outcome = response(request)
        else:
            outcome = response
        self.total_cost += float(outcome.cost_usd)
        return outcome

    def _lookup(self, request: ResearchRequest) -> Response | None:
        keys = (
            (request.product_id, request.composition_hash, request.parameter_id),
            (request.composition_hash, request.parameter_id),
            request.parameter_id,
        )
        for key in keys:
            if key in self._responses:
                return self._responses[key]
        return self._default


def candidate(
    *,
    parameter_id: str,
    claim: str,
    quote: str,
    url: str = "https://example.org/product",
    source_text: str | None = None,
    retrieved_at: str = "2026-10-01T00:00:00+00:00",
    direction: str = "supports",
    strength: str = "moderate",
    confidence: float = 0.8,
    source_type: str = "official",
    title: str = "Product page",
    extraction_method: str = "quote_extraction_v1",
) -> EvidenceCandidate:
    """Convenience builder for tests (source text defaults to the quote itself)."""
    return EvidenceCandidate(
        parameter_id=parameter_id,
        claim=claim,
        quote=quote,
        source=Source(
            url=url,
            title=title,
            source_type=source_type,
            retrieved_at=retrieved_at,
        ),
        source_text=quote if source_text is None else source_text,
        direction=direction,
        strength=strength,
        confidence=confidence,
        extraction_method=extraction_method,
    )


def ok(
    *candidates: EvidenceCandidate,
    score: int | None = None,
    rationale: str = "",
    proposal: AssessmentProposal | None = None,
    applicability: str = APPLICABLE,
    applicability_reason: str = "",
    sufficient: bool | None = None,
    limitations: tuple[str, ...] = (),
    contradictions: tuple[str, ...] = (),
    important_unknowns: tuple[str, ...] = (),
    evidence_refs: tuple[int, ...] | None = None,
    cost_usd: float = 0.0,
    tokens: tuple[int, int] = (0, 0),
) -> ResearchOutcome:
    """Build a successful provider outcome with a structured proposal.

    ``score`` is the model's chosen level; when it is ``None`` the proposal says
    "applicable, but not enough evidence", which the assessor stores without a
    number. Test-only helper: no network, no cost.
    """
    if proposal is None:
        if not candidates:
            raise EvidenceError("ok() needs candidates to bind the proposal")
        if not rationale:
            rationale = (
                f"Модель оценила соответствие требованию пункта как {score}/100."
                if score is not None
                else "Проверяемых данных недостаточно для обоснованной оценки."
            )
        proposal = AssessmentProposal(
            parameter_id=candidates[0].parameter_id,
            applicability=applicability,
            applicability_reason=applicability_reason,
            sufficient=(score is not None) if sufficient is None else sufficient,
            score=score,
            rationale=rationale,
            limitations=tuple(limitations),
            contradictions=tuple(contradictions),
            important_unknowns=tuple(important_unknowns),
            evidence_refs=(
                tuple(range(len(candidates))) if evidence_refs is None else evidence_refs
            ),
        )
    return ResearchOutcome(
        status=RESEARCH_OK,
        candidates=tuple(candidates),
        proposal=proposal,
        provider="fake",
        tokens_in=tokens[0],
        tokens_out=tokens[1],
        cost_usd=cost_usd,
    )


def insufficient(reason: str = "источники не найдены") -> ResearchOutcome:
    return ResearchOutcome(status=RESEARCH_INSUFFICIENT, error=reason, provider="fake")


def provider_error(reason: str = "provider timeout") -> ResearchOutcome:
    return ResearchOutcome(status=RESEARCH_PROVIDER_ERROR, error=reason, provider="fake")


def source_unavailable(reason: str = "источник недоступен") -> ResearchOutcome:
    return ResearchOutcome(status=RESEARCH_SOURCE_UNAVAILABLE, error=reason, provider="fake")
